**Custom Hooks Pattern:**
```typescript
// hooks/use{{Entity}}.ts
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'

export function use{{Entity}}s() {
  return useQuery({
    queryKey: ['{{entity}}s'],
    queryFn: fetch{{Entity}}s,
  })
}

export function useCreate{{Entity}}() {
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: create{{Entity}},
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['{{entity}}s'] })
    },
    onMutate: async (new{{Entity}}) => {
      // Optimistic update
      await queryClient.cancelQueries({ queryKey: ['{{entity}}s'] })
      const previous = queryClient.getQueryData(['{{entity}}s'])
      queryClient.setQueryData(['{{entity}}s'], (old) => [...old, new{{Entity}}])
      return { previous }
    },
    onError: (err, variables, context) => {
      queryClient.setQueryData(['{{entity}}s'], context.previous)
    },
  })
}
```

