**Advanced Queries:**
```typescript
// Complex filtering with relations
export async function getPosts(filters: PostFilters) {
  return prisma.post.findMany({
    where: {
      published: true,
      ...(filters.categoryId && { categoryId: filters.categoryId }),
      ...(filters.search && {
        OR: [
          { title: { contains: filters.search, mode: 'insensitive' } },
          { content: { contains: filters.search, mode: 'insensitive' } },
        ],
      }),
      ...(filters.tags && {
        tags: {
          some: {
            name: { in: filters.tags },
          },
        },
      }),
    },
    include: {
      author: {
        select: {
          id: true,
          name: true,
          avatar: true,
        },
      },
      category: true,
      tags: true,
      _count: {
        select: {
          comments: true,
          likes: true,
        },
      },
    },
    orderBy: {
      [filters.sortBy || 'createdAt']: filters.sortOrder || 'desc',
    },
    skip: (filters.page - 1) * filters.limit,
    take: filters.limit,
  })
}

// Aggregations
export async function getPostStats(postId: string) {
  return prisma.post.findUnique({
    where: { id: postId },
    select: {
      _count: {
        select: {
          comments: true,
          likes: true,
        },
      },
    },
  })
}

// Transactions
export async function createPostWithTags(data: CreatePostData) {
  return prisma.$transaction(async (tx) => {
    const post = await tx.post.create({
      data: {
        title: data.title,
        content: data.content,
        authorId: data.authorId,
      },
    })

    if (data.tags?.length) {
      await tx.post.update({
        where: { id: post.id },
        data: {
          tags: {
            connectOrCreate: data.tags.map((tag) => ({
              where: { name: tag },
              create: { name: tag },
            })),
          },
        },
      })
    }

    return post
  })
}

// Raw queries for complex operations
export async function getTrendingPosts() {
  return prisma.$queryRaw`
    SELECT 
      p.*,
      COUNT(l.id) as like_count,
      COUNT(c.id) as comment_count
    FROM posts p
    LEFT JOIN likes l ON p.id = l.post_id
    LEFT JOIN comments c ON p.id = c.post_id
    WHERE p.published = true
    AND p.created_at >= NOW() - INTERVAL '7 days'
    GROUP BY p.id
    ORDER BY (COUNT(l.id) + COUNT(c.id) * 2) DESC
    LIMIT 10
  `
}
```

**Middleware:**
```typescript
// Soft delete middleware
prisma.$use(async (params, next) => {
  if (params.model && params.action === 'delete') {
    params.action = 'update'
    params.args['data'] = { deletedAt: new Date() }
  }

  if (params.model && params.action === 'findMany') {
    if (!params.args) params.args = {}
    if (!params.args.where) params.args.where = {}
    params.args.where['deletedAt'] = null
  }

  return next(params)
})
```

